import empty = require( '@stdlib/ndarray/base/empty' );
import pop = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const order = 'row-major';
	const sh = [ 2, 2 ];

	pop( empty( 'float64', sh, order ), 1, false, false ); // $ExpectType Array
	pop( empty( 'complex64', sh, order ), 1, false, false ); // $ExpectType Array
	pop( empty( 'uint8c', sh, order ), 1, false, false ); // $ExpectType Array
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	pop( '10', 1, false, false ); // $ExpectError
	pop( 10, 1, false, false ); // $ExpectError
	pop( false, 1, false, false ); // $ExpectError
	pop( true, 1, false, false ); // $ExpectError
	pop( null, 1, false, false ); // $ExpectError
	pop( [], 1, false, false ); // $ExpectError
	pop( {}, 1, false, false ); // $ExpectError
	pop( ( x: number ): number => x, 1, false, false ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not an integer...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	pop( x, '5', false, false ); // $ExpectError
	pop( x, false, false, false ); // $ExpectError
	pop( x, true, false, false ); // $ExpectError
	pop( x, null, false, false ); // $ExpectError
	pop( x, undefined, false, false ); // $ExpectError
	pop( x, [ '5' ], false, false ); // $ExpectError
	pop( x, {}, false, false ); // $ExpectError
	pop( x, ( x: number ): number => x, false, false ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a boolean...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	pop( x, 1, '5', false ); // $ExpectError
	pop( x, 1, 5, false ); // $ExpectError
	pop( x, 1, null, false ); // $ExpectError
	pop( x, 1, undefined, false ); // $ExpectError
	pop( x, 1, [ '5' ], false ); // $ExpectError
	pop( x, 1, {}, false ); // $ExpectError
	pop( x, 1, ( x: number ): number => x, false ); // $ExpectError
}

// The compiler throws an error if the function is provided a fourth argument which is not a boolean...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	pop( x, 1, false, '5' ); // $ExpectError
	pop( x, 1, false, 5 ); // $ExpectError
	pop( x, 1, false, null ); // $ExpectError
	pop( x, 1, false, undefined ); // $ExpectError
	pop( x, 1, false, [ '5' ] ); // $ExpectError
	pop( x, 1, false, {} ); // $ExpectError
	pop( x, 1, false, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	pop( x ); // $ExpectError
	pop( x, 1 ); // $ExpectError
	pop( x, 1, false ); // $ExpectError
	pop( x, 1, false, false, {} ); // $ExpectError
}
